#' Staggered-Adoption Augmented Synthetic Control
#'
#' 
#' @param data .
#' @param outcome .
#' @param unit .
#' @param time .
#' @param treatInd .
#' @param adoption .
#' @param predictors Auxiliary covariates, averaged over the periods before
#'   the earliest adoption (missing values omitted), balanced together with the
#'   pre-treatment outcomes.
#' @param fixedeff .
#' @param timeCohort .
#' @param nuText Weight on the pooled balance relative to separate balance. 0
#'   fits each treated unit separately, 1 only balances the average.
#' @param lambda .
#' @param nLeads .
#' @param nLags .
#' @param infType .
#' @param nBoot .
#' @param alpha .
#' @param seed .
#' @param showWeights .
#' @param showGuide .
#' @param showHelp .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$guide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$helpText} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$summary} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$units} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$event} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$balance} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$weights} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$eventPlot} \tab \tab \tab \tab \tab an image \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$summary$asDF}
#'
#' \code{as.data.frame(results$summary)}
#'
#' @export
stagascm <- function(
    data,
    outcome,
    unit,
    time,
    treatInd,
    adoption,
    predictors,
    fixedeff = TRUE,
    timeCohort = FALSE,
    nuText = "",
    lambda = 0,
    nLeads = "",
    nLags = "",
    infType = "bootstrap",
    nBoot = 1000,
    alpha = 0.05,
    seed = 1,
    showWeights = FALSE,
    showGuide = FALSE,
    showHelp = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("stagascm requires jmvcore to be installed (restart may be required)")

    if ( ! missing(outcome)) outcome <- jmvcore::resolveQuo(jmvcore::enquo(outcome))
    if ( ! missing(unit)) unit <- jmvcore::resolveQuo(jmvcore::enquo(unit))
    if ( ! missing(time)) time <- jmvcore::resolveQuo(jmvcore::enquo(time))
    if ( ! missing(treatInd)) treatInd <- jmvcore::resolveQuo(jmvcore::enquo(treatInd))
    if ( ! missing(adoption)) adoption <- jmvcore::resolveQuo(jmvcore::enquo(adoption))
    if ( ! missing(predictors)) predictors <- jmvcore::resolveQuo(jmvcore::enquo(predictors))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(outcome), outcome, NULL),
            `if`( ! missing(unit), unit, NULL),
            `if`( ! missing(time), time, NULL),
            `if`( ! missing(treatInd), treatInd, NULL),
            `if`( ! missing(adoption), adoption, NULL),
            `if`( ! missing(predictors), predictors, NULL))


    options <- stagascmOptions$new(
        outcome = outcome,
        unit = unit,
        time = time,
        treatInd = treatInd,
        adoption = adoption,
        predictors = predictors,
        fixedeff = fixedeff,
        timeCohort = timeCohort,
        nuText = nuText,
        lambda = lambda,
        nLeads = nLeads,
        nLags = nLags,
        infType = infType,
        nBoot = nBoot,
        alpha = alpha,
        seed = seed,
        showWeights = showWeights,
        showGuide = showGuide,
        showHelp = showHelp)

    analysis <- stagascmClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

